def discover_task_files(run: VaultCheckRun) -> tuple[list[dict], list[str], list[str]]:
    """Collect current task entities plus review-ledger and archive paths."""
    tasks_dir = run.target / "vault" / "tasks"
    current: list[dict] = []
    ledgers: list[str] = []
    archive: list[str] = []
    if tasks_dir.is_symlink():
        # Reported by check_required_files; never enumerate through the link.
        return current, ledgers, archive
    try:
        entries = sorted(tasks_dir.iterdir(), key=lambda path: path.name)
    except OSError as exc:
        run.add("task-state", "FILE_UNREADABLE", "error", "vault/tasks", f"could not list vault/tasks/: {exc}")
        return current, ledgers, archive

    for entry in entries:
        relative = entry.relative_to(run.target).as_posix()
        if entry.name.startswith("."):
            continue
        if entry.is_symlink():
            run.add("task-state", "SYMLINK_INPUT", "error", relative, f"{relative} is a symbolic link; refusing to follow it")
            if REVIEW_LEDGER_RE.match(entry.name):
                ledgers.append(relative)
            elif TASK_FILE_ID_RE.match(entry.name) and entry.name.endswith(".md"):
                current.append({"path": relative, "task_id": TASK_FILE_ID_RE.match(entry.name).group(1), "lifecycle": None, "legacy": False, "valid": False, "state": None})
            continue
        if REVIEW_LEDGER_RE.match(entry.name):
            ledgers.append(relative)
            continue
        match = TASK_FILE_ID_RE.match(entry.name)
        if match is None or not entry.name.endswith(".md"):
            continue
        text, error = read_regular_text(entry)
        if error is not None or text is None:
            # (None, None): the entry vanished between listing and reading.
            if error is not None:
                run.add("task-state", "FILE_UNREADABLE", "error", relative, f"could not read {relative}: {error}")
            continue
        state, failures = parse_task_state_block(text)
        if failures is None:
            # (None, None): a legacy task file carries no state block.
            run.add(
                "task-state",
                "TASK_STATE_MISSING",
                "warning",
                relative,
                "legacy task file without a trellium-task-state block; lifecycle is unresolved",
                task_id=match.group(1),
            )
            current.append({"path": relative, "task_id": match.group(1), "lifecycle": None, "legacy": True, "valid": False, "state": None})
            continue
        if failures:
            for code, message in failures:
                run.add("task-state", code, "error", relative, message, task_id=match.group(1))
            current.append({"path": relative, "task_id": match.group(1), "lifecycle": None, "legacy": False, "valid": False, "state": None})
            continue
        if state["task_id"] != match.group(1):
            run.add(
                "task-state",
                "TASK_ID_MISMATCH",
                "error",
                relative,
                f"trellium-task-state task_id {state['task_id']!r} does not match the file name prefix {match.group(1)}",
                task_id=match.group(1),
            )
            current.append({"path": relative, "task_id": match.group(1), "lifecycle": None, "legacy": False, "valid": False, "state": None})
            continue
        current.append({"path": relative, "task_id": match.group(1), "lifecycle": state["lifecycle"], "legacy": False, "valid": True, "state": state})

    archive_dir = tasks_dir / "archive"
    if archive_dir.is_symlink():
        run.add("task-state", "SYMLINK_INPUT", "error", "vault/tasks/archive", "vault/tasks/archive/ is a symbolic link; refusing to follow it")
    elif archive_dir.is_dir():
        for entry in sorted(archive_dir.iterdir(), key=lambda path: path.name):
            if not (TASK_FILE_ID_RE.match(entry.name) and entry.name.endswith(".md")):
                continue
            relative = entry.relative_to(run.target).as_posix()
            if entry.is_symlink():
                run.add("task-state", "SYMLINK_INPUT", "error", relative, f"{relative} is a symbolic link; refusing to follow it")
            archive.append(relative)

    id_counts: dict[str, int] = {}
    for task in current:
        id_counts[task["task_id"]] = id_counts.get(task["task_id"], 0) + 1
    for task in current:
        if id_counts[task["task_id"]] > 1:
            run.add(
                "task-state",
                "TASK_ID_DUPLICATE",
                "error",
                task["path"],
                f"task_id {task['task_id']} is declared by {id_counts[task['task_id']]} task files; keep exactly one current task per id",
                task_id=task["task_id"],
            )
            task["valid"] = False
    return current, ledgers, archive


def parse_task_state_block(text: str) -> tuple[dict | None, list[tuple[str, str]] | None]:
    """Return (state, []) on success, (None, None) for legacy, or (None, failures)."""
    blocks, error = extract_comment_blocks(text, TASK_STATE_MARKER)
    if error is not None:
        return None, [("TASK_STATE_INVALID", error)]
    if not blocks:
        return None, None
    if len(blocks) > 1:
        return None, [
            ("TASK_STATE_DUPLICATE", f"expected at most one {TASK_STATE_MARKER} block, found {len(blocks)}")
        ]
    state, error = parse_block_object(blocks[0])
    if state is None:
        return None, [("TASK_STATE_INVALID", f"invalid {TASK_STATE_MARKER} block: {error}")]
    validation_errors = validate_state_object(state)
    if validation_errors:
        return None, [
            ("TASK_STATE_INVALID", f"invalid {TASK_STATE_MARKER} block: {message}")
            for message in validation_errors
        ]
    return state, []


def check_runtime_projection(run: VaultCheckRun, runtime_text: str | None, tasks: list[dict], policy: dict | None = None) -> None:
    if runtime_text is None:
        return
    by_id: dict[str, list[dict]] = {}
    for task in tasks:
        by_id.setdefault(task["task_id"], []).append(task)

    closed_lifecycles = {"accepted", "superseded"}
    storage = policy.get("task_storage") if isinstance(policy, dict) else None
    local_mode = storage == "local"
    reported_missing_local: set[str] = set()

    def resolve(task_id: str, row_status: str | None = None) -> None:
        if row_counts.get(task_id, 0) > 1:
            # TASK_RUNTIME_DUPLICATE already covers this task; freshness/closed
            # inference must not depend on the order of the duplicate rows.
            return
        matches = by_id.get(task_id)
        if not matches:
            if local_mode:
                if task_id in reported_missing_local:
                    return
                reported_missing_local.add(task_id)
                if row_status in closed_lifecycles:
                    run.add(
                        "runtime-projection",
                        "TASK_RUNTIME_CLOSED_LOCAL",
                        "error",
                        "vault/runtime.md",
                        f"local task {task_id} is closed ({row_status}) but its runtime row still exists; remove the stale row from runtime.md — closed local tasks stay out of the hot path, and durable conclusions belong in canonical vault files",
                        task_id=task_id,
                    )
                else:
                    run.add(
                        "runtime-projection",
                        "TASK_RUNTIME_LOCAL_UNRESOLVED",
                        "warning",
                        "vault/runtime.md",
                        f"runtime points to local task {task_id}, but its file is not in this worktree: this is expected in a fresh clone (local task files are ignored) or the file may have been lost locally; recover the original task file or rebuild the contract with owner approval; the runtime summary is an unverified clue and grants no authority",
                        task_id=task_id,
                    )
            else:
                run.add("runtime-projection", "TASK_RUNTIME_MISSING", "error", "vault/runtime.md", f"runtime points to a task file that does not exist: {task_id}", task_id=task_id)
            return
        task = matches[0]
        if task["legacy"]:
            run.add("runtime-projection", "TASK_RUNTIME_UNRESOLVED", "warning", "vault/runtime.md", f"runtime row for {task_id} cannot be verified: the task file has no trellium-task-state block (legacy)", task_id=task_id)
        elif task.get("lifecycle") is None:
            run.add("runtime-projection", "TASK_RUNTIME_UNRESOLVED", "warning", "vault/runtime.md", f"runtime row for {task_id} cannot be verified: the task state block is invalid", task_id=task_id)

    rows, focus, problems = parse_runtime_task_pointers(runtime_text)
    for _kind, detail in problems:
        run.add("runtime-projection", "TASK_RUNTIME_INVALID", "error", "vault/runtime.md", detail)

    row_counts: dict[str, int] = {}
    for task_id, _status, _objective, _next_action in rows:
        row_counts[task_id] = row_counts.get(task_id, 0) + 1
    for task_id, count in row_counts.items():
        if count > 1:
            run.add(
                "runtime-projection",
                "TASK_RUNTIME_DUPLICATE",
                "error",
                "vault/runtime.md",
                f"Active Tasks table has {count} rows for {task_id}; keep one row per task",
                task_id=task_id,
            )

    projected = set(row_counts)
    for task in tasks:
        if not task["valid"] or task["lifecycle"] in closed_lifecycles:
            continue
        if task["task_id"] not in projected:
            run.add(
                "runtime-projection",
                "TASK_PROJECTION_MISSING",
                "error",
                "vault/runtime.md",
                f"open task {task['task_id']} ({task['lifecycle']}) has no Active Tasks row in runtime.md; the runtime projection is missing",
                task_id=task["task_id"],
            )

    for task_id, status, _objective, _next_action in rows:
        resolve(task_id, status)
        matches = by_id.get(task_id) or []
        task = matches[0] if matches else None
        if task is None or task["legacy"] or task.get("lifecycle") is None:
            continue
        if local_mode and task["lifecycle"] in closed_lifecycles:
            run.add(
                "runtime-projection",
                "TASK_RUNTIME_CLOSED_LOCAL",
                "error",
                "vault/runtime.md",
                f"local task {task_id} is closed ({task['lifecycle']}) but its runtime row still exists; remove the stale row from runtime.md — closed local tasks stay out of the hot path, and durable conclusions belong in canonical vault files",
                task_id=task_id,
            )
        if status not in LIFECYCLE_VALUES:
            run.add("runtime-projection", "TASK_RUNTIME_INVALID", "error", "vault/runtime.md", f"Active Tasks row for {task_id} uses status {status!r} outside the lifecycle enum", task_id=task_id)
        elif status != task["lifecycle"]:
            run.add(
                "runtime-projection",
                "TASK_RUNTIME_DRIFT",
                "error",
                "vault/runtime.md",
                f"runtime row for {task_id} says {status!r} but the trellium-task-state block says {task['lifecycle']!r}",
                task_id=task_id,
            )
    for task_id in focus:
        resolve(task_id)


def measure_hot_files(run: VaultCheckRun, texts: dict[str, str]) -> None:
    definitions = (
        ("runtime", "vault/runtime.md", "recent_entries", count_recent_entries),
        ("handoff", "vault/handoff.md", "entries", count_handoff_entries),
        ("decisions", "vault/decisions.md", "records", count_decision_records),

# --- Vault status (read-only) -----------------------------------------------
#
# `status` compiles the same checked state layer as `check` into an owner
# summary: focus, open-task classification, closed counts, and explicit
# unresolved entries. It adds no facts and claims no authority: lifecycle and
# authority come only from validated task state blocks, runtime rows only
# contribute their objective/Next Action projection, and anything else is
# reported as unresolved with the blocking finding codes. Closed tasks appear
# as counts only. Like `check`, it never writes, never follows symlinks into
# vault inputs, and never executes content.

STATUS_OPEN_LIFECYCLES = ("draft", "active", "blocked", "ready_for_review")
CLOSED_LIFECYCLES = frozenset({"accepted", "superseded"})

# Finding codes that make a task's lifecycle undeterminable. Runtime rows are
# projections: a drifted row demotes the task to unresolved instead of letting
# either side win, while storage and budget findings never demote a lifecycle
# that the state block owns.
STATUS_UNRESOLVED_CODES = frozenset({
    "FILE_UNREADABLE",
    "SYMLINK_INPUT",
    "TASK_ID_DUPLICATE",
    "TASK_ID_MISMATCH",
    "TASK_RUNTIME_DRIFT",
    "TASK_RUNTIME_LOCAL_UNRESOLVED",
    "TASK_RUNTIME_MISSING",
    "TASK_RUNTIME_UNRESOLVED",
    "TASK_STATE_DUPLICATE",
    "TASK_STATE_INVALID",
    "TASK_STATE_MISSING",
})


def status_unresolved_reasons(findings: list[dict]) -> dict[str, list[str]]:
    """Map task ids to ordered unique finding codes that block classification."""
    reasons: dict[str, list[str]] = {}
    for finding in findings:
        code = finding["code"]
        if code not in STATUS_UNRESOLVED_CODES:
            continue
        task_id = finding.get("task_id")
        if task_id is None:
            # Path-only findings name current task files only: review ledgers
            # and archive/ entries are cold history, never current state.
            path = finding["path"]
            name = Path(path).name
            match = TASK_FILE_ID_RE.match(name)
            if (
                match is None
                or REVIEW_LEDGER_RE.match(name) is not None
                or path.startswith("vault/tasks/archive/")
            ):
                continue
            task_id = match.group(1)
        if task_id is None:
            continue
        codes = reasons.setdefault(task_id, [])
        if code not in codes:
            codes.append(code)
    return reasons


def build_status_payload(
    target: Path,
    run: VaultCheckRun,
    texts: dict[str, str],
    tasks: list[dict],
) -> dict:
    findings = run.sorted_findings()
    runtime_text = texts.get("vault/runtime.md")
    rows: list[tuple[str, str, str, str]] = []
    focus_ids: list[str] = []
    if runtime_text is not None:
        rows, focus_ids, _problems = parse_runtime_task_pointers(runtime_text)

    # One projection per task: duplicated or enum-invalid rows cannot quote a
    # trustworthy Next Action, so their tasks lose the projection but keep the
    # lifecycle owned by their state block.
    invalid_row_ids = {
        finding["task_id"]
        for finding in findings
        if finding["code"] == "TASK_RUNTIME_INVALID" and "task_id" in finding
    }
    row_counts: dict[str, int] = {}
    projections: dict[str, dict] = {}
    for task_id, _status, objective, next_action in rows:
        row_counts[task_id] = row_counts.get(task_id, 0) + 1
        if row_counts[task_id] == 1 and task_id not in invalid_row_ids:
            projections[task_id] = {"objective": objective, "next_action": next_action}
        elif task_id in projections:
            del projections[task_id]

    reasons = status_unresolved_reasons(findings)
    open_buckets: dict[str, list[dict]] = {lifecycle: [] for lifecycle in STATUS_OPEN_LIFECYCLES}
    unresolved: list[dict] = []
    unresolved_ids: set[str] = set()
    resolved_ids: set[str] = set()
    closed = 0

    def unresolved_entry(task_id: str, path: str | None) -> dict:
        entry: dict = {
            "task_id": task_id,
            "reason": ",".join(reasons.get(task_id) or ["TASK_RUNTIME_UNRESOLVED"]),
        }
        if path is not None:
            entry["task_path"] = path
        return entry

    for task in tasks:
        task_id = task["task_id"]
        drifted = "TASK_RUNTIME_DRIFT" in reasons.get(task_id, [])
        if not task["valid"] or drifted:
            if task_id not in unresolved_ids:
                unresolved_ids.add(task_id)
                # A duplicated id spans several files; the findings list keeps
                # every path, so the entry stays pathless instead of picking one.
                ambiguous = "TASK_ID_DUPLICATE" in reasons.get(task_id, [])
                unresolved.append(unresolved_entry(task_id, None if ambiguous else task["path"]))
            continue
        resolved_ids.add(task_id)
        if task["lifecycle"] in CLOSED_LIFECYCLES:
            closed += 1
            continue
        state = task["state"]
        item: dict = {
            "task_id": task_id,
            "lifecycle": task["lifecycle"],
            "authority_level": state["authority_level"],
            "task_path": task["path"],
        }
        if "current_slice" in state:
            item["current_slice"] = state["current_slice"]
        if "gates" in state:
            item["gates"] = state["gates"]
        if task_id in projections:
            item["runtime_projection"] = projections[task_id]
        open_buckets[task["lifecycle"]].append(item)

    # Runtime rows and focus pointers that resolve to no classified task stay
    # visible as unresolved without inventing lifecycle or authority.
    for task_id in row_counts:
        if task_id in resolved_ids or task_id in unresolved_ids:
            continue
        unresolved_ids.add(task_id)
        unresolved.append(unresolved_entry(task_id, None))
    for task_id in focus_ids:
        if task_id in resolved_ids or task_id in unresolved_ids:
            continue
        unresolved_ids.add(task_id)
        unresolved.append(unresolved_entry(task_id, None))
    # A current task file can also fail before any record exists (unreadable,
    # not a regular file); its id still belongs in unresolved.
    for task_id in sorted(reasons):
        if task_id in resolved_ids or task_id in unresolved_ids:
            continue
        unresolved_ids.add(task_id)
        unresolved.append(unresolved_entry(task_id, None))
    unresolved.sort(key=lambda entry: entry["task_id"])

    return {
        "schema_version": 1,
        "target": str(target),
        "focus": [
            {"task_id": task_id, "resolved": task_id in resolved_ids}
            for task_id in focus_ids
        ],
        "summary": {
            "draft": len(open_buckets["draft"]),
            "active": len(open_buckets["active"]),
            "blocked": len(open_buckets["blocked"]),
            "ready_for_review": len(open_buckets["ready_for_review"]),
            "closed": closed,
            "unresolved": len(unresolved),
        },
        "tasks": {
            "ready_for_review": open_buckets["ready_for_review"],
            "blocked": open_buckets["blocked"],
            "active": open_buckets["active"],
            "draft": open_buckets["draft"],
            "unresolved": unresolved,
        },
        "findings": findings,
    }


def render_status_text(payload: dict) -> None:
    print(f"trellium status: {payload['target']}")
    if payload["focus"]:
        focus_cells = [
            f"{item['task_id']} ({'resolved' if item['resolved'] else 'unresolved'})"
            for item in payload["focus"]
        ]
        print(f"focus: {', '.join(focus_cells)}")
    else:
        print("focus: (none)")
    summary = payload["summary"]
    print(
        "summary: {draft} draft, {active} active, {blocked} blocked, "
        "{ready_for_review} ready_for_review, {closed} closed, {unresolved} unresolved".format(**summary)
    )
    for lifecycle in STATUS_OPEN_LIFECYCLES:
        items = payload["tasks"][lifecycle]
        if not items:
            print(f"{lifecycle}: (none)")
            continue
        print(f"{lifecycle} ({len(items)}):")
        for item in items:
            head = f"  {item['task_id']} authority={item['authority_level']}"
            if "current_slice" in item:
                head += f" slice={item['current_slice']}"
            if "gates" in item:
                gates = ", ".join(f"{gate}={value}" for gate, value in sorted(item["gates"].items()))
                head += f" gates: {gates}"
            head += f" path={item['task_path']}"
            print(head)
            projection = item.get("runtime_projection")
            if projection is not None:
                if projection["objective"]:
                    print(f"    objective: {projection['objective']}")
                if projection["next_action"]:
                    print(f"    next: {projection['next_action']}")
    unresolved = payload["tasks"]["unresolved"]
    if not unresolved:
        print("unresolved: (none)")
    else:
        print(f"unresolved ({len(unresolved)}):")
        for item in unresolved:
            line = f"  {item['task_id']} reason={item['reason']}"
            if "task_path" in item:
                line += f" path={item['task_path']}"
            print(line)
    findings = payload["findings"]
    if not findings:
        print("findings: none")
    else:
        print(f"findings ({len(findings)}):")
        for finding in findings:
            task_suffix = f" [{finding['task_id']}]" if "task_id" in finding else ""
            print(f"  {finding['severity'].upper():<7} {finding['code']} {finding['path']}{task_suffix}: {finding['message']}")
    errors = sum(1 for finding in findings if finding["severity"] == "error")
    warnings = sum(1 for finding in findings if finding["severity"] == "warning")
    print(f"result: {errors} error(s), {warnings} warning(s)")


